/**
 * Traducciones de los 9 discursos clave del Papa León XIV a los 8 idiomas
 * no-ES. Source of truth: data/discursos.ts (español).
 */

import type { Locale } from '@/data/i18n/types'
import { discursos, tiposDiscurso, type Discurso, type TipoDiscursoLabel } from '@/data/discursos'

type DiscursoTranslation = {
  titulo: string
  lugar: string
  ocasion: string
  resumen: string
  fragmento: string
}

const DISCURSOS_EN: DiscursoTranslation[] = [
  { titulo: 'First greeting from the Vatican Loggia', lugar: 'Central balcony of St. Peter\'s Basilica, Vatican City', ocasion: 'Appearance of the new pontiff after his election', resumen: 'First public words of Pope Leo XIV minutes after his election. Addressed to the crowd gathered in St. Peter\'s Square, the message focused on peace, human dignity and ecclesial communion.', fragmento: 'Peace be with all of you. Thank you, dear brothers, for this gathering. The peace of the risen Christ, an unarmed and disarming peace, humble and persevering. We want to be a synodal Church, a Church that walks, a Church that builds bridges, always open to welcome like this square with open arms.' },
  { titulo: 'Address to the College of Cardinals', lugar: 'Synod Hall, Vatican City', ocasion: 'First audience with the cardinals after the election', resumen: 'The Pope explains for the first time the reason for choosing the name Leo and outlines the programmatic lines of his pontificate: social doctrine, artificial intelligence and continuity with the teaching of Leo XIII.', fragmento: 'I have chosen the name Leo because Pope Leo XIII, with the historic encyclical Rerum Novarum, addressed the social question in the context of the first great industrial revolution. Today the Church offers to all her heritage of social doctrine to respond to another industrial revolution: that of artificial intelligence, which poses new challenges to the defence of human dignity, justice and labour.' },
  { titulo: 'Homily at the Mass for the beginning of the pontificate', lugar: 'St. Peter\'s Square, Vatican City', ocasion: 'Solemn celebration of the beginning of the Petrine ministry', resumen: 'Homily read before 200,000 faithful, 150 official delegations and the College of Cardinals. The Pope develops the idea of the pastor as servant and reaffirms his pastoral programme of unity, service to the poor and care of the common home.', fragmento: 'Peter was not called for his qualities —he was a fisherman, impulsive, fragile— but by the love of the Lord who sought him. This ministry I receive today is not an honour, it is a burden; it is not a power, it is a service; it is not a privilege, it is a vocation to give my life for my brothers, especially for the smallest, the poorest, the most forgotten.' },
  { titulo: 'First general audience', lugar: 'St. Peter\'s Square, Vatican City', ocasion: 'Start of the weekly catechesis cycle of the pontificate', resumen: 'The Pope inaugurates his Wednesday general audiences with a catechesis on Christian hope and announces a cycle dedicated to "The names of God in the Bible".', fragmento: 'Christian hope is not cheap optimism or psychological projection. It is the certainty that Christ has conquered death and walks with us. That is why we do not fear the darkness of the world: look at the stars, they are the same ones our ancestors saw, the same God who spoke to them speaks to us today.' },
  { titulo: 'Message to the G7 on artificial intelligence', lugar: 'Sent to the G7 in Rome, Vatican City', ocasion: 'Vatican participation in the G7 summit on AI', resumen: 'Following the lead of Pope Francis\'s 2024 message to the G7, Leo XIV insists on the need for international governance of AI centred on human dignity. One of the first major programmatic interventions of his pontificate.', fragmento: 'Artificial intelligence cannot make decisions affecting life and human dignity without responsible human oversight. No machine should decide who lives and who dies, who works and who is discarded, who is protected and who is abandoned. Dignity is not computed.' },
  { titulo: 'Message for the World Day of Migrants and Refugees', lugar: 'Vatican City', ocasion: '111th World Day of Migrants and Refugees', resumen: 'First major pontifical message on migration. Draws on his pastoral experience in Chiclayo and links the migration question to social doctrine, preparing the ground for his visit to the Canary Islands in 2026.', fragmento: 'For thirty years I lived in northern Peru, a land marked by the continuous movement of people in search of life. I have understood that no wall is higher than human dignity, and that migration, before being a political problem, is a concrete face of Christ knocking at our door.' },
  { titulo: 'Urbi et Orbi Christmas Message', lugar: 'Central Loggia of St. Peter\'s, Vatican City', ocasion: 'First Christmas as pontiff', resumen: 'First Urbi et Orbi message of the pontificate. Tour of the main open conflicts on the planet (Ukraine, Gaza, Sudan, Myanmar, Haiti) and call for unarmed peace. Concludes with the apostolic blessing granting the plenary indulgence.', fragmento: 'On this day when God has become a child, when omnipotence has chosen fragility, we look to Bethlehem. We also look to today\'s Bethlehems: Ukraine, Gaza, Sudan, Myanmar, Haiti, Congo. Children born among rubble. Mothers giving birth in refugee camps. For all of them we ask for unarmed and disarming peace.' },
  { titulo: 'Message for the 59th World Day of Peace', lugar: 'Vatican City', ocasion: 'Solemnity of Mary, Mother of God', resumen: 'First message for the World Day of Peace of the pontificate. Title: "Disarm words, disarm the earth". Reflection on public language, disinformation, generative AI and consequences in real conflicts.', fragmento: 'Before bombs fall, words fall: those that dehumanise, that delegitimise, that morally prepare violence. Disarming words is the first step to disarming the earth. And this also applies to the new forms of synthetic language that artificial intelligence generates with astonishing ease.' },
  { titulo: 'Annual address to the Roman Curia', lugar: 'Sala Clementina, Apostolic Palace', ocasion: 'Christmas greetings to the Roman Curia', resumen: 'First annual address to the Curia. Marks the reformist tone of continuity with Francis: simplicity, decentralisation and service. Introduces the reform of three dicasteries and announces the first apostolic exhortation Dilexi Te.', fragmento: 'A Curia that does not serve has no reason to exist. May we not be courtiers but collaborators of the Successor of Peter and servants of the particular churches. Reform has not ended: it will continue, not out of activism, but because the Church is always on the way of conversion.' },
]

const DISCURSOS_IT: DiscursoTranslation[] = [
  { titulo: 'Primo saluto dalla Loggia Vaticana', lugar: 'Loggia centrale della Basilica di San Pietro, Città del Vaticano', ocasion: 'Affacciata del nuovo Pontefice dopo l\'elezione', resumen: 'Prime parole pubbliche di Papa Leone XIV pochi minuti dopo l\'elezione. Rivolto alla folla riunita in Piazza San Pietro, il messaggio si è concentrato sulla pace, la dignità umana e la comunione ecclesiale.', fragmento: 'La pace sia con tutti voi. Grazie, cari fratelli, per questo incontro. La pace del Cristo risorto, una pace disarmata e disarmante, umile e perseverante. Vogliamo essere una Chiesa sinodale, una Chiesa che cammina, una Chiesa che costruisce ponti, sempre aperta ad accogliere come questa piazza con le braccia aperte.' },
  { titulo: 'Discorso al Collegio Cardinalizio', lugar: 'Aula del Sinodo, Città del Vaticano', ocasion: 'Prima udienza con i cardinali dopo l\'elezione', resumen: 'Il Papa spiega per la prima volta il motivo della scelta del nome Leone e traccia le linee programmatiche del suo pontificato: dottrina sociale, intelligenza artificiale e continuità con il magistero di Leone XIII.', fragmento: 'Ho scelto il nome di Leone perché Papa Leone XIII, con la storica enciclica Rerum Novarum, affrontò la questione sociale nel contesto della prima grande rivoluzione industriale. Oggi la Chiesa offre a tutti il suo patrimonio di dottrina sociale per rispondere a un\'altra rivoluzione industriale: quella dell\'intelligenza artificiale, che pone nuove sfide alla difesa della dignità umana, della giustizia e del lavoro.' },
  { titulo: 'Omelia della Messa di inizio del pontificato', lugar: 'Piazza San Pietro, Città del Vaticano', ocasion: 'Celebrazione solenne dell\'inizio del ministero petrino', resumen: 'Omelia pronunciata davanti a 200.000 fedeli, 150 delegazioni ufficiali e il Collegio Cardinalizio. Il Papa sviluppa l\'idea del pastore come servo e riafferma il suo programma pastorale di unità, servizio ai poveri e cura della casa comune.', fragmento: 'Pietro non fu chiamato per le sue qualità —era un pescatore, impulsivo, fragile— ma per l\'amore del Signore che lo cercò. Questo ministero che oggi ricevo non è un onore, è un peso; non è un potere, è un servizio; non è un privilegio, è una vocazione a dare la vita per i fratelli, specialmente per i più piccoli, i più poveri, i più dimenticati.' },
  { titulo: 'Prima udienza generale', lugar: 'Piazza San Pietro, Città del Vaticano', ocasion: 'Inizio del ciclo di catechesi settimanali del pontificato', resumen: 'Il Papa inaugura le sue udienze generali del mercoledì con una catechesi sulla speranza cristiana e annuncia un ciclo dedicato a "I nomi di Dio nella Bibbia".', fragmento: 'La speranza cristiana non è un ottimismo a buon mercato né una proiezione psicologica. È la certezza che Cristo ha vinto la morte e cammina con noi. Per questo non temiamo le tenebre del mondo: guardate le stelle, sono le stesse che vedevano i nostri padri, lo stesso Dio che parlava loro parla anche a noi oggi.' },
  { titulo: 'Messaggio al G7 sull\'intelligenza artificiale', lugar: 'Inviato al G7 di Roma, Città del Vaticano', ocasion: 'Partecipazione vaticana al vertice G7 sull\'IA', resumen: 'Sulla scia del messaggio di Papa Francesco al G7 del 2024, Leone XIV insiste sulla necessità di una governance internazionale dell\'IA centrata sulla dignità umana. Uno dei primi grandi interventi programmatici del suo pontificato.', fragmento: 'L\'intelligenza artificiale non può prendere decisioni che riguardano la vita e la dignità umana senza una supervisione umana responsabile. Nessuna macchina deve decidere chi vive e chi muore, chi lavora e chi viene scartato, chi è protetto e chi è abbandonato. La dignità non si computa.' },
  { titulo: 'Messaggio per la Giornata Mondiale del Migrante e del Rifugiato', lugar: 'Città del Vaticano', ocasion: '111ª Giornata Mondiale del Migrante e del Rifugiato', resumen: 'Primo grande messaggio pontificio sulle migrazioni. Attinge alla sua esperienza pastorale a Chiclayo e collega la questione migratoria alla dottrina sociale, preparando il terreno per il viaggio alle Canarie nel 2026.', fragmento: 'Per trent\'anni ho vissuto nel nord del Perù, una terra segnata dal continuo movimento di persone in cerca di vita. Ho compreso che nessun muro è più alto della dignità umana, e che la migrazione, prima di essere un problema politico, è un volto concreto di Cristo che bussa alla nostra porta.' },
  { titulo: 'Messaggio Urbi et Orbi del Natale', lugar: 'Loggia centrale di San Pietro, Città del Vaticano', ocasion: 'Primo Natale da Pontefice', resumen: 'Primo messaggio Urbi et Orbi del pontificato. Rassegna dei principali conflitti aperti del pianeta (Ucraina, Gaza, Sudan, Myanmar, Haiti) e appello alla pace disarmata. Si conclude con la benedizione apostolica con concessione dell\'indulgenza plenaria.', fragmento: 'In questo giorno in cui Dio si è fatto bambino, in cui l\'onnipotenza ha scelto la fragilità, guardiamo a Betlemme. Guardiamo anche alle Betlemmi di oggi: Ucraina, Gaza, Sudan, Myanmar, Haiti, Congo. Bambini nati tra le macerie. Madri che partoriscono in campi profughi. Per tutti loro chiediamo una pace disarmata e disarmante.' },
  { titulo: 'Messaggio per la 59ª Giornata Mondiale della Pace', lugar: 'Città del Vaticano', ocasion: 'Solennità di Maria Madre di Dio', resumen: 'Primo messaggio per la Giornata Mondiale della Pace del pontificato. Titolo: "Disarmare le parole, disarmare la terra". Riflessione su linguaggio pubblico, disinformazione, IA generativa e conseguenze nei conflitti reali.', fragmento: 'Prima delle bombe cadono le parole: quelle che disumanizzano, che delegittimano, che preparano moralmente la violenza. Disarmare le parole è il primo passo per disarmare la terra. E questo vale anche per le nuove forme di linguaggio sintetico che l\'intelligenza artificiale genera con stupefacente facilità.' },
  { titulo: 'Discorso annuale alla Curia Romana', lugar: 'Sala Clementina, Palazzo Apostolico', ocasion: 'Auguri natalizi alla Curia Romana', resumen: 'Primo discorso annuale alla Curia. Segna il tono riformatore in continuità con Francesco: semplicità, decentramento e servizio. Introduce la riforma di tre dicasteri e annuncia la prima esortazione apostolica Dilexi Te.', fragmento: 'Una Curia che non serve non ha ragione di esistere. Non siamo cortigiani, ma collaboratori del Successore di Pietro e servitori delle Chiese particolari. La riforma non è terminata: continuerà, non per attivismo, ma perché la Chiesa è sempre sulla via della conversione.' },
]

const DISCURSOS_FR: DiscursoTranslation[] = [
  { titulo: 'Premier salut depuis la Loge vaticane', lugar: 'Balcon central de la basilique Saint-Pierre, Cité du Vatican', ocasion: 'Présentation du nouveau Pontife après son élection', resumen: 'Premières paroles publiques du Pape Léon XIV quelques minutes après son élection. Adressées à la foule rassemblée place Saint-Pierre, le message s\'est centré sur la paix, la dignité humaine et la communion ecclésiale.', fragmento: 'Que la paix soit avec vous tous. Merci, chers frères, pour ce rassemblement. La paix du Christ ressuscité, une paix désarmée et désarmante, humble et persévérante. Nous voulons être une Église synodale, une Église qui marche, une Église qui construit des ponts, toujours ouverte à accueillir comme cette place aux bras ouverts.' },
  { titulo: 'Discours au Collège cardinalice', lugar: 'Salle du Synode, Cité du Vatican', ocasion: 'Première audience avec les cardinaux après l\'élection', resumen: 'Le Pape explique pour la première fois le motif du choix du nom de Léon et trace les lignes programmatiques de son pontificat : doctrine sociale, intelligence artificielle et continuité avec le magistère de Léon XIII.', fragmento: 'J\'ai choisi le nom de Léon parce que le Pape Léon XIII, avec l\'historique encyclique Rerum Novarum, a affronté la question sociale dans le contexte de la première grande révolution industrielle. Aujourd\'hui, l\'Église offre à tous son patrimoine de doctrine sociale pour répondre à une autre révolution industrielle : celle de l\'intelligence artificielle, qui pose de nouveaux défis à la défense de la dignité humaine, de la justice et du travail.' },
  { titulo: 'Homélie de la Messe du début du pontificat', lugar: 'Place Saint-Pierre, Cité du Vatican', ocasion: 'Célébration solennelle du début du ministère pétrinien', resumen: 'Homélie prononcée devant 200 000 fidèles, 150 délégations officielles et le Collège cardinalice. Le Pape développe l\'idée du pasteur comme serviteur et réaffirme son programme pastoral d\'unité, de service aux pauvres et de soin de la maison commune.', fragmento: 'Pierre ne fut pas appelé pour ses qualités —il était pêcheur, impulsif, fragile— mais par l\'amour du Seigneur qui le chercha. Ce ministère que je reçois aujourd\'hui n\'est pas un honneur, c\'est un fardeau ; ce n\'est pas un pouvoir, c\'est un service ; ce n\'est pas un privilège, c\'est une vocation à donner ma vie pour mes frères, surtout pour les plus petits, les plus pauvres, les plus oubliés.' },
  { titulo: 'Première audience générale', lugar: 'Place Saint-Pierre, Cité du Vatican', ocasion: 'Début du cycle de catéchèses hebdomadaires du pontificat', resumen: 'Le Pape inaugure ses audiences générales du mercredi par une catéchèse sur l\'espérance chrétienne et annonce un cycle consacré à « Les noms de Dieu dans la Bible ».', fragmento: 'L\'espérance chrétienne n\'est ni un optimisme bon marché ni une projection psychologique. C\'est la certitude que le Christ a vaincu la mort et marche avec nous. C\'est pourquoi nous ne craignons pas les ténèbres du monde : regardez les étoiles, ce sont les mêmes que celles que voyaient nos pères, le même Dieu qui leur parlait nous parle aussi aujourd\'hui.' },
  { titulo: 'Message au G7 sur l\'intelligence artificielle', lugar: 'Envoyé au G7 de Rome, Cité du Vatican', ocasion: 'Participation vaticane au sommet du G7 sur l\'IA', resumen: 'Dans la lignée du message du Pape François au G7 de 2024, Léon XIV insiste sur la nécessité d\'une gouvernance internationale de l\'IA centrée sur la dignité humaine. L\'une des premières grandes interventions programmatiques de son pontificat.', fragmento: 'L\'intelligence artificielle ne peut pas prendre de décisions qui touchent à la vie et à la dignité humaine sans une supervision humaine responsable. Aucune machine ne doit décider qui vit et qui meurt, qui travaille et qui est rejeté, qui est protégé et qui est abandonné. La dignité ne se calcule pas.' },
  { titulo: 'Message pour la Journée mondiale du migrant et du réfugié', lugar: 'Cité du Vatican', ocasion: '111ᵉ Journée mondiale du migrant et du réfugié', resumen: 'Premier grand message pontifical sur les migrations. Il s\'inspire de son expérience pastorale à Chiclayo et relie la question migratoire à la doctrine sociale, préparant le terrain pour son voyage aux Canaries en 2026.', fragmento: 'Pendant trente ans j\'ai vécu dans le nord du Pérou, une terre marquée par le mouvement continu de personnes en quête de vie. J\'ai compris qu\'aucun mur n\'est plus haut que la dignité humaine, et que la migration, avant d\'être un problème politique, est un visage concret du Christ qui frappe à notre porte.' },
  { titulo: 'Message Urbi et Orbi de Noël', lugar: 'Loge centrale de Saint-Pierre, Cité du Vatican', ocasion: 'Premier Noël comme Pontife', resumen: 'Premier message Urbi et Orbi du pontificat. Tour d\'horizon des principaux conflits ouverts sur la planète (Ukraine, Gaza, Soudan, Myanmar, Haïti) et appel à la paix désarmée. Se conclut par la bénédiction apostolique avec concession de l\'indulgence plénière.', fragmento: 'En ce jour où Dieu s\'est fait enfant, où la toute-puissance a choisi la fragilité, nous regardons Bethléem. Nous regardons aussi les Bethléem d\'aujourd\'hui : Ukraine, Gaza, Soudan, Myanmar, Haïti, Congo. Des enfants nés parmi les ruines. Des mères qui accouchent dans des camps de réfugiés. Pour tous, nous demandons une paix désarmée et désarmante.' },
  { titulo: 'Message pour la 59ᵉ Journée mondiale de la paix', lugar: 'Cité du Vatican', ocasion: 'Solennité de Marie, Mère de Dieu', resumen: 'Premier message pour la Journée mondiale de la paix du pontificat. Titre : « Désarmer les paroles, désarmer la terre ». Réflexion sur le langage public, la désinformation, l\'IA générative et les conséquences dans les conflits réels.', fragmento: 'Avant les bombes tombent les paroles : celles qui déshumanisent, qui délégitiment, qui préparent moralement la violence. Désarmer les paroles est le premier pas pour désarmer la terre. Et cela vaut aussi pour les nouvelles formes de langage synthétique que l\'intelligence artificielle génère avec une étonnante facilité.' },
  { titulo: 'Discours annuel à la Curie romaine', lugar: 'Salle Clémentine, Palais apostolique', ocasion: 'Vœux de Noël à la Curie romaine', resumen: 'Premier discours annuel à la Curie. Marque le ton réformateur en continuité avec François : simplicité, décentralisation et service. Introduit la réforme de trois dicastères et annonce la première exhortation apostolique Dilexi Te.', fragmento: 'Une Curie qui ne sert pas n\'a pas de raison d\'exister. Que nous ne soyons pas des courtisans, mais des collaborateurs du Successeur de Pierre et des serviteurs des Églises particulières. La réforme n\'est pas terminée : elle continuera, non par activisme, mais parce que l\'Église est toujours sur le chemin de la conversion.' },
]

const DISCURSOS_DE: DiscursoTranslation[] = [
  { titulo: 'Erster Gruß von der Vatikanloggia', lugar: 'Mittelloggia der Petersbasilika, Vatikanstadt', ocasion: 'Vorstellung des neuen Pontifex nach der Wahl', resumen: 'Erste öffentliche Worte von Papst Leo XIV. wenige Minuten nach seiner Wahl. An die auf dem Petersplatz versammelte Menge gerichtet, konzentrierte sich die Botschaft auf den Frieden, die Menschenwürde und die kirchliche Communio.', fragmento: 'Der Friede sei mit euch allen. Danke, liebe Brüder, für diese Versammlung. Der Friede des auferstandenen Christus, ein entwaffneter und entwaffnender Friede, demütig und beharrlich. Wir wollen eine synodale Kirche sein, eine Kirche, die geht, eine Kirche, die Brücken baut, immer offen zur Aufnahme wie dieser Platz mit seinen offenen Armen.' },
  { titulo: 'Ansprache an das Kardinalskollegium', lugar: 'Synodenaula, Vatikanstadt', ocasion: 'Erste Audienz mit den Kardinälen nach der Wahl', resumen: 'Der Papst erläutert zum ersten Mal den Grund für die Wahl des Namens Leo und zeichnet die programmatischen Linien seines Pontifikats: Soziallehre, künstliche Intelligenz und Kontinuität mit dem Magisterium Leos XIII.', fragmento: 'Ich habe den Namen Leo gewählt, weil Papst Leo XIII. mit der historischen Enzyklika Rerum Novarum die soziale Frage im Kontext der ersten großen industriellen Revolution aufgriff. Heute bietet die Kirche allen ihr Erbe der Soziallehre an, um auf eine andere industrielle Revolution zu antworten: die der künstlichen Intelligenz, die der Verteidigung der Menschenwürde, der Gerechtigkeit und der Arbeit neue Herausforderungen stellt.' },
  { titulo: 'Predigt zur Heiligen Messe zum Beginn des Pontifikats', lugar: 'Petersplatz, Vatikanstadt', ocasion: 'Feierliche Eröffnung des petrinischen Dienstes', resumen: 'Vor 200.000 Gläubigen, 150 offiziellen Delegationen und dem Kardinalskollegium gehaltene Predigt. Der Papst entfaltet den Gedanken vom Hirten als Diener und bekräftigt sein pastorales Programm der Einheit, des Dienstes an den Armen und der Sorge für das gemeinsame Haus.', fragmento: 'Petrus wurde nicht wegen seiner Eigenschaften berufen —er war ein Fischer, impulsiv, zerbrechlich—, sondern durch die Liebe des Herrn, der ihn suchte. Dieses Amt, das ich heute empfange, ist keine Ehre, sondern eine Last; keine Macht, sondern ein Dienst; kein Privileg, sondern eine Berufung, mein Leben für die Brüder hinzugeben, besonders für die Geringsten, die Ärmsten, die Vergessensten.' },
  { titulo: 'Erste Generalaudienz', lugar: 'Petersplatz, Vatikanstadt', ocasion: 'Beginn des wöchentlichen Katechesezyklus des Pontifikats', resumen: 'Der Papst eröffnet seine Generalaudienzen am Mittwoch mit einer Katechese über die christliche Hoffnung und kündigt einen Zyklus zum Thema „Die Namen Gottes in der Bibel" an.', fragmento: 'Die christliche Hoffnung ist weder billiger Optimismus noch psychologische Projektion. Sie ist die Gewissheit, dass Christus den Tod besiegt hat und mit uns geht. Deshalb fürchten wir die Finsternis der Welt nicht: schaut zu den Sternen, es sind dieselben, die unsere Väter sahen, derselbe Gott, der zu ihnen sprach, spricht heute zu uns.' },
  { titulo: 'Botschaft an die G7 zur künstlichen Intelligenz', lugar: 'An die G7 in Rom gesandt, Vatikanstadt', ocasion: 'Vatikanische Teilnahme am G7-Gipfel zur KI', resumen: 'In der Linie der Botschaft Papst Franziskus\' an die G7 von 2024 unterstreicht Leo XIV. die Notwendigkeit einer internationalen KI-Governance, die auf der Menschenwürde gründet. Eine der ersten großen programmatischen Interventionen seines Pontifikats.', fragmento: 'Künstliche Intelligenz darf keine Entscheidungen treffen, die Leben und Menschenwürde betreffen, ohne verantwortliche menschliche Aufsicht. Keine Maschine soll entscheiden, wer lebt und wer stirbt, wer arbeitet und wer ausgesondert wird, wer geschützt und wer verlassen wird. Würde wird nicht berechnet.' },
  { titulo: 'Botschaft zum Welttag der Migranten und Flüchtlinge', lugar: 'Vatikanstadt', ocasion: '111. Welttag der Migranten und Flüchtlinge', resumen: 'Erste große päpstliche Botschaft zur Migration. Schöpft aus seiner pastoralen Erfahrung in Chiclayo und verknüpft die Migrationsfrage mit der Soziallehre, womit der Boden für seine Reise auf die Kanaren 2026 bereitet wird.', fragmento: 'Dreißig Jahre lang lebte ich im Norden Perus, einem Land, das vom ständigen Aufbruch von Menschen auf der Suche nach Leben geprägt ist. Ich habe verstanden, dass keine Mauer höher ist als die Menschenwürde, und dass die Migration, bevor sie ein politisches Problem ist, ein konkretes Antlitz Christi ist, der an unsere Tür klopft.' },
  { titulo: 'Urbi-et-Orbi-Botschaft zu Weihnachten', lugar: 'Mittelloggia der Petersbasilika, Vatikanstadt', ocasion: 'Erstes Weihnachten als Pontifex', resumen: 'Erste Urbi-et-Orbi-Botschaft des Pontifikats. Rundgang durch die wichtigsten offenen Konflikte auf der Welt (Ukraine, Gaza, Sudan, Myanmar, Haiti) und Aufruf zum entwaffneten Frieden. Endet mit dem apostolischen Segen mit Verleihung des vollkommenen Ablasses.', fragmento: 'An diesem Tag, an dem Gott Kind geworden ist, an dem die Allmacht die Zerbrechlichkeit gewählt hat, blicken wir auf Bethlehem. Wir blicken auch auf die heutigen Bethlehems: Ukraine, Gaza, Sudan, Myanmar, Haiti, Kongo. Kinder, die unter Trümmern geboren werden. Mütter, die in Flüchtlingslagern entbinden. Für sie alle erbitten wir einen entwaffneten und entwaffnenden Frieden.' },
  { titulo: 'Botschaft zum 59. Weltfriedenstag', lugar: 'Vatikanstadt', ocasion: 'Hochfest der Gottesmutter Maria', resumen: 'Erste Botschaft zum Weltfriedenstag des Pontifikats. Titel: „Die Worte entwaffnen, die Erde entwaffnen". Reflexion über öffentliche Sprache, Desinformation, generative KI und Folgen in realen Konflikten.', fragmento: 'Vor den Bomben fallen die Worte: jene, die entmenschlichen, die delegitimieren, die die Gewalt sittlich vorbereiten. Die Worte zu entwaffnen ist der erste Schritt, um die Erde zu entwaffnen. Und das gilt auch für die neuen Formen synthetischer Sprache, die die künstliche Intelligenz mit erstaunlicher Leichtigkeit erzeugt.' },
  { titulo: 'Jährliche Ansprache an die Römische Kurie', lugar: 'Sala Clementina, Apostolischer Palast', ocasion: 'Weihnachtsglückwünsche an die Römische Kurie', resumen: 'Erste jährliche Ansprache an die Kurie. Kennzeichnet den reformerischen Ton in Kontinuität mit Franziskus: Schlichtheit, Dezentralisierung und Dienst. Führt die Reform dreier Dikasterien ein und kündigt die erste apostolische Exhortation Dilexi Te an.', fragmento: 'Eine Kurie, die nicht dient, hat keine Daseinsberechtigung. Wir wollen keine Hofleute sein, sondern Mitarbeiter des Petrusnachfolgers und Diener der Teilkirchen. Die Reform ist nicht abgeschlossen: sie wird weitergehen, nicht aus Aktionismus, sondern weil die Kirche immer auf dem Weg der Bekehrung ist.' },
]

const DISCURSOS_PT: DiscursoTranslation[] = [
  { titulo: 'Primeira saudação da Loggia Vaticana', lugar: 'Varanda central da Basílica de São Pedro, Cidade do Vaticano', ocasion: 'Apresentação do novo Pontífice após a sua eleição', resumen: 'Primeiras palavras públicas do Papa Leão XIV poucos minutos depois da sua eleição. Dirigidas à multidão reunida na Praça de São Pedro, a mensagem centrou-se na paz, na dignidade humana e na comunhão eclesial.', fragmento: 'A paz esteja com todos vós. Obrigado, queridos irmãos, por este encontro. A paz do Cristo ressuscitado, uma paz desarmada e desarmante, humilde e perseverante. Queremos ser uma Igreja sinodal, uma Igreja que caminha, uma Igreja que constrói pontes, sempre aberta a acolher como esta praça com os seus braços abertos.' },
  { titulo: 'Discurso ao Colégio Cardinalício', lugar: 'Sala do Sínodo, Cidade do Vaticano', ocasion: 'Primeira audiência com os cardeais após a eleição', resumen: 'O Papa explica pela primeira vez o motivo da escolha do nome Leão e traça as linhas programáticas do seu pontificado: doutrina social, inteligência artificial e continuidade com o magistério de Leão XIII.', fragmento: 'Escolhi o nome de Leão porque o Papa Leão XIII, com a histórica encíclica Rerum Novarum, enfrentou a questão social no contexto da primeira grande revolução industrial. Hoje a Igreja oferece a todos o seu património de doutrina social para responder a outra revolução industrial: a da inteligência artificial, que coloca novos desafios à defesa da dignidade humana, da justiça e do trabalho.' },
  { titulo: 'Homilia na Missa de início do pontificado', lugar: 'Praça de São Pedro, Cidade do Vaticano', ocasion: 'Celebração solene do início do ministério petrino', resumen: 'Homilia proferida diante de 200.000 fiéis, 150 delegações oficiais e o Colégio Cardinalício. O Papa desenvolve a ideia do pastor como servo e reafirma o seu programa pastoral de unidade, serviço aos pobres e cuidado da casa comum.', fragmento: 'Pedro não foi chamado pelas suas qualidades —era um pescador, impulsivo, frágil— mas pelo amor do Senhor que o procurou. Este ministério que hoje recebo não é uma honra, é um peso; não é um poder, é um serviço; não é um privilégio, é uma vocação a dar a vida pelos irmãos, especialmente pelos mais pequenos, os mais pobres, os mais esquecidos.' },
  { titulo: 'Primeira audiência geral', lugar: 'Praça de São Pedro, Cidade do Vaticano', ocasion: 'Início do ciclo de catequeses semanais do pontificado', resumen: 'O Papa inaugura as suas audiências gerais de quarta-feira com uma catequese sobre a esperança cristã e anuncia um ciclo dedicado a "Os nomes de Deus na Bíblia".', fragmento: 'A esperança cristã não é otimismo barato nem projeção psicológica. É a certeza de que Cristo venceu a morte e caminha connosco. Por isso não tememos as trevas do mundo: olhem para as estrelas, são as mesmas que viam os nossos pais, o mesmo Deus que falava com eles fala connosco hoje.' },
  { titulo: 'Mensagem ao G7 sobre inteligência artificial', lugar: 'Enviada ao G7 em Roma, Cidade do Vaticano', ocasion: 'Participação vaticana na cúpula do G7 sobre IA', resumen: 'Na linha da mensagem do Papa Francisco ao G7 de 2024, Leão XIV insiste na necessidade de uma governança internacional da IA centrada na dignidade humana. Uma das primeiras grandes intervenções programáticas do seu pontificado.', fragmento: 'A inteligência artificial não pode tomar decisões que afetem a vida e a dignidade humana sem uma supervisão humana responsável. Nenhuma máquina deve decidir quem vive e quem morre, quem trabalha e quem é descartado, quem é protegido e quem é abandonado. A dignidade não se computa.' },
  { titulo: 'Mensagem para o Dia Mundial do Migrante e do Refugiado', lugar: 'Cidade do Vaticano', ocasion: '111º Dia Mundial do Migrante e do Refugiado', resumen: 'Primeira grande mensagem pontifícia sobre migrações. Inspira-se na sua experiência pastoral em Chiclayo e liga a questão migratória à doutrina social, preparando o terreno para a sua viagem às Canárias em 2026.', fragmento: 'Durante trinta anos vivi no norte do Peru, uma terra marcada pelo movimento contínuo de pessoas em busca de vida. Compreendi que nenhum muro é mais alto do que a dignidade humana, e que a migração, antes de ser um problema político, é um rosto concreto de Cristo que bate à nossa porta.' },
  { titulo: 'Mensagem Urbi et Orbi do Natal', lugar: 'Loggia central de São Pedro, Cidade do Vaticano', ocasion: 'Primeiro Natal como Pontífice', resumen: 'Primeira mensagem Urbi et Orbi do pontificado. Percurso pelos principais conflitos abertos do planeta (Ucrânia, Gaza, Sudão, Myanmar, Haiti) e apelo à paz desarmada. Termina com a bênção apostólica concedendo a indulgência plenária.', fragmento: 'Neste dia em que Deus se fez criança, em que a omnipotência escolheu a fragilidade, olhamos para Belém. Olhamos também para os Belém de hoje: Ucrânia, Gaza, Sudão, Myanmar, Haiti, Congo. Crianças nascidas entre escombros. Mães que dão à luz em campos de refugiados. Por todos eles pedimos uma paz desarmada e desarmante.' },
  { titulo: 'Mensagem para o 59º Dia Mundial da Paz', lugar: 'Cidade do Vaticano', ocasion: 'Solenidade de Maria Mãe de Deus', resumen: 'Primeira mensagem para o Dia Mundial da Paz do pontificado. Título: "Desarmar as palavras, desarmar a terra". Reflexão sobre linguagem pública, desinformação, IA generativa e consequências nos conflitos reais.', fragmento: 'Antes das bombas caem as palavras: as que desumanizam, as que deslegitimam, as que preparam moralmente a violência. Desarmar as palavras é o primeiro passo para desarmar a terra. E isto vale também para as novas formas de linguagem sintética que a inteligência artificial gera com espantosa facilidade.' },
  { titulo: 'Discurso anual à Cúria Romana', lugar: 'Sala Clementina, Palácio Apostólico', ocasion: 'Felicitações de Natal à Cúria Romana', resumen: 'Primeiro discurso anual à Cúria. Marca o tom reformador em continuidade com Francisco: simplicidade, descentralização e serviço. Introduz a reforma de três dicastérios e anuncia a primeira exortação apostólica Dilexi Te.', fragmento: 'Uma Cúria que não serve não tem razão de existir. Que não sejamos cortesãos, mas colaboradores do Sucessor de Pedro e servidores das Igrejas particulares. A reforma não terminou: continuará, não por ativismo, mas porque a Igreja está sempre no caminho da conversão.' },
]

const DISCURSOS_CA: DiscursoTranslation[] = [
  { titulo: 'Primera salutació des de la Lògia Vaticana', lugar: 'Balcó central de la Basílica de Sant Pere, Ciutat del Vaticà', ocasion: 'Presentació del nou Pontífex després de la seva elecció', resumen: 'Primeres paraules públiques del Papa Lleó XIV pocs minuts després de la seva elecció. Adreçades a la multitud reunida a la Plaça de Sant Pere, el missatge se centrà en la pau, la dignitat humana i la comunió eclesial.', fragmento: 'La pau sigui amb tots vosaltres. Gràcies, estimats germans, per aquesta trobada. La pau del Crist ressuscitat, una pau desarmada i desarmant, humil i perseverant. Volem ser una Església sinodal, una Església que camina, una Església que construeix ponts, sempre oberta a acollir com aquesta plaça amb els braços oberts.' },
  { titulo: 'Discurs al Col·legi Cardenalici', lugar: 'Aula del Sínode, Ciutat del Vaticà', ocasion: 'Primera audiència amb els cardenals després de l\'elecció', resumen: 'El Papa explica per primera vegada el motiu de l\'elecció del nom Lleó i traça les línies programàtiques del seu pontificat: doctrina social, intel·ligència artificial i continuïtat amb el magisteri de Lleó XIII.', fragmento: 'He escollit el nom de Lleó perquè el Papa Lleó XIII, amb la històrica encíclica Rerum Novarum, va afrontar la qüestió social en el context de la primera gran revolució industrial. Avui l\'Església ofereix a tothom el seu patrimoni de doctrina social per respondre a una altra revolució industrial: la de la intel·ligència artificial, que planteja nous reptes a la defensa de la dignitat humana, la justícia i el treball.' },
  { titulo: 'Homilia a la Missa d\'inici del pontificat', lugar: 'Plaça de Sant Pere, Ciutat del Vaticà', ocasion: 'Celebració solemne de l\'inici del ministeri petrí', resumen: 'Homilia pronunciada davant de 200.000 fidels, 150 delegacions oficials i el Col·legi Cardenalici. El Papa desenvolupa la idea del pastor com a servent i reafirma el seu programa pastoral d\'unitat, servei als pobres i cura de la casa comuna.', fragmento: 'Pere no fou cridat per les seves qualitats —era un pescador, impulsiu, fràgil— sinó per l\'amor del Senyor que el cercà. Aquest ministeri que avui rebo no és un honor, és una càrrega; no és un poder, és un servei; no és un privilegi, és una vocació a donar la vida pels germans, especialment pels més petits, els més pobres, els més oblidats.' },
  { titulo: 'Primera audiència general', lugar: 'Plaça de Sant Pere, Ciutat del Vaticà', ocasion: 'Inici del cicle de catequesis setmanals del pontificat', resumen: 'El Papa inaugura les seves audiències generals dels dimecres amb una catequesi sobre l\'esperança cristiana i anuncia un cicle dedicat a "Els noms de Déu a la Bíblia".', fragmento: 'L\'esperança cristiana no és optimisme barat ni projecció psicològica. És la certesa que Crist ha vençut la mort i camina amb nosaltres. Per això no temem les tenebres del món: mireu els estels, són els mateixos que veien els nostres pares, el mateix Déu que els parlava ens parla també a nosaltres avui.' },
  { titulo: 'Missatge al G7 sobre la intel·ligència artificial', lugar: 'Enviat al G7 de Roma, Ciutat del Vaticà', ocasion: 'Participació vaticana a la cimera del G7 sobre la IA', resumen: 'En la línia del missatge del Papa Francesc al G7 de 2024, Lleó XIV insisteix en la necessitat d\'una governança internacional de la IA centrada en la dignitat humana. Una de les primeres grans intervencions programàtiques del seu pontificat.', fragmento: 'La intel·ligència artificial no pot prendre decisions que afecten la vida i la dignitat humana sense una supervisió humana responsable. Cap màquina ha de decidir qui viu i qui mor, qui treballa i qui és descartat, qui és protegit i qui és abandonat. La dignitat no es computa.' },
  { titulo: 'Missatge per a la Jornada Mundial del Migrant i del Refugiat', lugar: 'Ciutat del Vaticà', ocasion: '111a Jornada Mundial del Migrant i del Refugiat', resumen: 'Primer gran missatge pontifici sobre migracions. S\'inspira en la seva experiència pastoral a Chiclayo i lliga la qüestió migratòria a la doctrina social, preparant el terreny per al seu viatge a les Canàries el 2026.', fragmento: 'Durant trenta anys vaig viure al nord del Perú, una terra marcada pel moviment continu de persones a la recerca de vida. He entès que cap mur no és més alt que la dignitat humana, i que la migració, abans de ser un problema polític, és un rostre concret de Crist que truca a la nostra porta.' },
  { titulo: 'Missatge Urbi et Orbi de Nadal', lugar: 'Lògia central de Sant Pere, Ciutat del Vaticà', ocasion: 'Primer Nadal com a Pontífex', resumen: 'Primer missatge Urbi et Orbi del pontificat. Recorregut pels principals conflictes oberts del planeta (Ucraïna, Gaza, Sudan, Myanmar, Haití) i crida a la pau desarmada. Conclou amb la benedicció apostòlica amb concessió de la indulgència plenària.', fragmento: 'En aquest dia en què Déu s\'ha fet infant, en què l\'omnipotència ha triat la fragilitat, mirem Betlem. Mirem també els Betlems d\'avui: Ucraïna, Gaza, Sudan, Myanmar, Haití, Congo. Infants nascuts entre runes. Mares que infanten en camps de refugiats. Per a tots ells demanem una pau desarmada i desarmant.' },
  { titulo: 'Missatge per a la 59a Jornada Mundial de la Pau', lugar: 'Ciutat del Vaticà', ocasion: 'Solemnitat de Maria Mare de Déu', resumen: 'Primer missatge per a la Jornada Mundial de la Pau del pontificat. Títol: "Desarmar les paraules, desarmar la terra". Reflexió sobre el llenguatge públic, la desinformació, la IA generativa i les conseqüències en els conflictes reals.', fragmento: 'Abans que les bombes cauen les paraules: les que deshumanitzen, les que deslegitimen, les que preparen moralment la violència. Desarmar les paraules és el primer pas per desarmar la terra. I això val també per a les noves formes de llenguatge sintètic que la intel·ligència artificial genera amb sorprenent facilitat.' },
  { titulo: 'Discurs anual a la Cúria Romana', lugar: 'Sala Clementina, Palau Apostòlic', ocasion: 'Felicitacions de Nadal a la Cúria Romana', resumen: 'Primer discurs anual a la Cúria. Marca el to reformista en continuïtat amb Francesc: senzillesa, descentralització i servei. Introdueix la reforma de tres dicasteris i anuncia la primera exhortació apostòlica Dilexi Te.', fragmento: 'Una Cúria que no serveix no té raó d\'existir. Que no siguem cortesans sinó col·laboradors del Successor de Pere i servidors de les Esglésies particulars. La reforma no s\'ha acabat: continuarà, no per activisme, sinó perquè l\'Església sempre està en el camí de la conversió.' },
]

const DISCURSOS_GL: DiscursoTranslation[] = [
  { titulo: 'Primeiro saúdo desde a Lóxia Vaticana', lugar: 'Balcón central da Basílica de San Pedro, Cidade do Vaticano', ocasion: 'Presentación do novo Pontífice tras a súa elección', resumen: 'Primeiras palabras públicas do Papa León XIV poucos minutos despois da súa elección. Dirixidas á multitude reunida na Praza de San Pedro, a mensaxe centrouse na paz, a dignidade humana e a comuñón eclesial.', fragmento: 'A paz sexa con todos vós. Grazas, queridos irmáns, por este encontro. A paz do Cristo resucitado, unha paz desarmada e desarmante, humilde e perseverante. Queremos ser unha Igrexa sinodal, unha Igrexa que camiña, unha Igrexa que constrúe pontes, sempre aberta a acoller coma esta praza cos brazos abertos.' },
  { titulo: 'Discurso ao Colexio Cardinalicio', lugar: 'Aula do Sínodo, Cidade do Vaticano', ocasion: 'Primeira audiencia cos cardeais tras a elección', resumen: 'O Papa explica por primeira vez o motivo da elección do nome León e traza as liñas programáticas do seu pontificado: doutrina social, intelixencia artificial e continuidade co maxisterio de León XIII.', fragmento: 'Escollín o nome de León porque o Papa León XIII, coa histórica encíclica Rerum Novarum, afrontou a cuestión social no contexto da primeira gran revolución industrial. Hoxe a Igrexa ofrece a todos o seu patrimonio de doutrina social para responder a outra revolución industrial: a da intelixencia artificial, que pon novos retos á defensa da dignidade humana, da xustiza e do traballo.' },
  { titulo: 'Homilía da Misa de inicio do pontificado', lugar: 'Praza de San Pedro, Cidade do Vaticano', ocasion: 'Celebración solemne do inicio do ministerio petrino', resumen: 'Homilía pronunciada ante 200.000 fieis, 150 delegacións oficiais e o Colexio Cardinalicio. O Papa desenvolve a idea do pastor como servo e reafirma o seu programa pastoral de unidade, servizo aos pobres e coidado da casa común.', fragmento: 'Pedro non foi chamado polas súas calidades —era un pescador, impulsivo, fráxil— senón polo amor do Señor que o procurou. Este ministerio que hoxe recibo non é unha honra, é unha carga; non é un poder, é un servizo; non é un privilexio, é unha vocación a dar a vida polos irmáns, especialmente polos máis pequenos, os máis pobres, os máis esquecidos.' },
  { titulo: 'Primeira audiencia xeral', lugar: 'Praza de San Pedro, Cidade do Vaticano', ocasion: 'Inicio do ciclo de catequeses semanais do pontificado', resumen: 'O Papa inaugura as súas audiencias xerais dos mércores cunha catequese sobre a esperanza cristiá e anuncia un ciclo dedicado a "Os nomes de Deus na Biblia".', fragmento: 'A esperanza cristiá non é optimismo barato nin proxección psicolóxica. É a certeza de que Cristo venceu a morte e camiña connosco. Por iso non tememos as tebras do mundo: ollade as estrelas, son as mesmas que vían os nosos pais, o mesmo Deus que lles falaba fálanos a nós hoxe.' },
  { titulo: 'Mensaxe ao G7 sobre intelixencia artificial', lugar: 'Enviada ao G7 en Roma, Cidade do Vaticano', ocasion: 'Participación vaticana na cumbre do G7 sobre IA', resumen: 'Na liña da mensaxe do Papa Francisco ao G7 de 2024, León XIV insiste na necesidade dunha gobernanza internacional da IA centrada na dignidade humana. Unha das primeiras grandes intervencións programáticas do seu pontificado.', fragmento: 'A intelixencia artificial non pode tomar decisións que afecten a vida e a dignidade humana sen unha supervisión humana responsable. Ningunha máquina debe decidir quen vive e quen morre, quen traballa e quen é descartado, quen é protexido e quen é abandonado. A dignidade non se computa.' },
  { titulo: 'Mensaxe para a Xornada Mundial do Migrante e do Refuxiado', lugar: 'Cidade do Vaticano', ocasion: '111ª Xornada Mundial do Migrante e do Refuxiado', resumen: 'Primeira gran mensaxe pontificia sobre migracións. Inspírase na súa experiencia pastoral en Chiclayo e liga a cuestión migratoria á doutrina social, preparando o terreo para a súa viaxe a Canarias en 2026.', fragmento: 'Durante trinta anos vivín no norte do Perú, unha terra marcada polo movemento continuo de persoas á procura de vida. Comprendín que ningún muro é máis alto que a dignidade humana, e que a migración, antes de ser un problema político, é un rostro concreto de Cristo que peta na nosa porta.' },
  { titulo: 'Mensaxe Urbi et Orbi do Nadal', lugar: 'Lóxia central de San Pedro, Cidade do Vaticano', ocasion: 'Primeiro Nadal como Pontífice', resumen: 'Primeira mensaxe Urbi et Orbi do pontificado. Percorrido polos principais conflitos abertos do planeta (Ucraína, Gaza, Sudán, Myanmar, Haití) e chamamento á paz desarmada. Conclúe coa bendición apostólica con concesión da indulxencia plenaria.', fragmento: 'Neste día no que Deus se fixo neno, no que a omnipotencia escolleu a fraxilidade, ollamos a Belén. Ollamos tamén aos Beléns de hoxe: Ucraína, Gaza, Sudán, Myanmar, Haití, Congo. Nenos nados entre escombros. Nais que dan a luz en campos de refuxiados. Por todos eles pedimos unha paz desarmada e desarmante.' },
  { titulo: 'Mensaxe para a 59ª Xornada Mundial da Paz', lugar: 'Cidade do Vaticano', ocasion: 'Solemnidade de María Nai de Deus', resumen: 'Primeira mensaxe para a Xornada Mundial da Paz do pontificado. Título: "Desarmar as palabras, desarmar a terra". Reflexión sobre linguaxe pública, desinformación, IA xenerativa e consecuencias nos conflitos reais.', fragmento: 'Antes das bombas caen as palabras: as que deshumanizan, as que deslexitiman, as que preparan moralmente a violencia. Desarmar as palabras é o primeiro paso para desarmar a terra. E isto vale tamén para as novas formas de linguaxe sintética que a intelixencia artificial xera con asombrosa facilidade.' },
  { titulo: 'Discurso anual á Curia Romana', lugar: 'Sala Clementina, Palacio Apostólico', ocasion: 'Felicitacións de Nadal á Curia Romana', resumen: 'Primeiro discurso anual á Curia. Marca o ton reformista en continuidade con Francisco: sinxeleza, descentralización e servizo. Introduce a reforma de tres dicasterios e anuncia a primeira exhortación apostólica Dilexi Te.', fragmento: 'Unha Curia que non serve non ten razón de existir. Que non sexamos cortesáns senón colaboradores do Sucesor de Pedro e servidores das Igrexas particulares. A reforma non rematou: continuará, non por activismo, senón porque a Igrexa sempre está no camiño da conversión.' },
]

const DISCURSOS_EU: DiscursoTranslation[] = [
  { titulo: 'Lehen agurra Vatikanoko Lojiatik', lugar: 'San Pedro Basilikako erdiko balkoia, Vatikano Hiria', ocasion: 'Pontifize berriaren agerpena hauteskundearen ondoren', resumen: 'Leon XIV. Aita Santuaren lehen hitz publikoak hautatu eta minutu gutxi geroago. San Pedro Plazan bildutako jendetzari zuzenduak, mezua bakean, giza duintasunean eta komunio eklesialean oinarritu zen.', fragmento: 'Bakea zuekin guztiokin. Eskerrik asko, anaia maiteok, topaketa honengatik. Kristo piztuaren bakea, bake desarmatua eta desarmatzailea, apala eta iraunkorra. Eliza sinodala izan nahi dugu, oinez doan Eliza, zubiak eraikitzen dituen Eliza, beti irekia harrera egiteko, beso zabalak dituen plaza hau bezala.' },
  { titulo: 'Kardinal Kolegioari hitzaldia', lugar: 'Sinodoaren aretoa, Vatikano Hiria', ocasion: 'Kardinalekin lehen entzunaldia hauteskundearen ondoren', resumen: 'Aita Santuak lehen aldiz Leon izena hautatzeko arrazoia azaltzen du, eta bere pontifikatuaren ildo programatikoak markatzen ditu: dotrina soziala, adimen artifiziala eta Leon XIII.aren magisterioarekiko jarraitutasuna.', fragmento: 'Leon izena hautatu dut, Leon XIII. Aita Santuak, Rerum Novarum entziklika historikoarekin, gizarte-galderari aurre egin zion lehen iraultza industrial handiaren testuinguruan. Gaur egun Elizak guztiei eskaintzen die bere dotrina sozialaren ondarea, beste iraultza industrial bati erantzuteko: adimen artifizialarena, giza duintasunaren, justiziaren eta lanaren defentsari erronka berriak ezartzen dizkiona.' },
  { titulo: 'Pontifikatu hasierako Mezako homilia', lugar: 'San Pedro Plaza, Vatikano Hiria', ocasion: 'Petriniar ministerioaren hasierako ospakizun ohorezkoa', resumen: '200.000 fededunen, 150 ordezkaritza ofizialen eta Kardinal Kolegioaren aurrean emandako homilia. Aita Santuak artzaina-zerbitzari ideia garatzen du eta bere programa pastorala berresten du: batasuna, behartsuei zerbitzua eta etxe komunaren ardura.', fragmento: 'Pedro ez zen bere ezaugarriengatik deitua izan —arrantzalea zen, bulkadakorra, hauskorra—, baizik eta bila zihoan Jaunaren maitasunagatik. Gaur hartzen dudan ministerio hau ez da ohore bat, zama bat da; ez da botere bat, zerbitzu bat da; ez da pribilegio bat, anaien aldera, batez ere txikienen, behartsuenen eta ahaztuenen aldera, bizia ematera bokazioa da.' },
  { titulo: 'Lehen entzunaldi orokorra', lugar: 'San Pedro Plaza, Vatikano Hiria', ocasion: 'Pontifikatuaren asteroko katekesi-zikloaren hasiera', resumen: 'Aita Santuak asteazkenetako entzunaldi orokorrak inauguratzen ditu kristau itxaropenari buruzko katekesi batekin, eta "Bibliako Jainkoaren izenak" gaiari eskainitako zikloa iragartzen du.', fragmento: 'Kristau itxaropena ez da merkeko baikortasuna, ezta proiekzio psikologiko bat ere. Kristok heriotza garaitu duela eta gurekin doalako ziurtasuna da. Horregatik ez ditugu munduko ilunkarak izutzat hartzen: begira izarrei, gure gurasoek ikusten zituztenak dira, hari mintzatzen zitzaion Jainko bera mintzatzen zaigu gaur.' },
  { titulo: 'G7-ari adimen artifizialari buruzko mezua', lugar: 'Erromako G7-ra bidalia, Vatikano Hiria', ocasion: 'Vatikanoaren parte-hartzea G7-ren IAri buruzko gailurrean', resumen: 'Frantzisko Aita Santuak 2024an G7-ari igorri zion mezuaren ildotik, Leon XIV.ak IAren nazioarteko gobernantza giza duintasunaren inguruan beharrezkoa dela azpimarratzen du. Bere pontifikatuaren lehen esku-hartze programatiko handietako bat.', fragmento: 'Adimen artifizialak ezin ditu giza bizia eta duintasuna ukitzen dituzten erabakiak hartu, gizakiaren ardurazko gainbegiraketarik gabe. Inolako makinak ez du erabaki behar nork bizi behar duen eta nork hil, nork lan egiten duen eta nor baztertzen den, nor babestua eta nor abandonatua. Duintasuna ez da konputatzen.' },
  { titulo: 'Migratzaileen eta Errefuxiatuen Mundu Egunerako mezua', lugar: 'Vatikano Hiria', ocasion: '111. Migratzaileen eta Errefuxiatuen Mundu Eguna', resumen: 'Migrazioei buruzko lehen mezu pontifikal handia. Chiclayoko bere esperientzia pastoraletik edaten du eta migrazio-gaia dotrina sozialarekin lotzen du, 2026ko Kanarietako bidaiarako bidea zabalduz.', fragmento: 'Hogeita hamar urtez bizi izan nintzen Peruko iparraldean, bizi bila dabilen jendearen mugimendu etengabeak markatzen duen lurraldean. Ulertu dut ez dagoela giza duintasuna baino harresi altuagorik, eta migrazioa, arazo politiko bat izan baino lehen, gure atea jotzen duen Kristoren aurpegi konkretua dela.' },
  { titulo: 'Eguberriko Urbi et Orbi mezua', lugar: 'San Pedroko erdiko Lojia, Vatikano Hiria', ocasion: 'Pontifize gisa lehen Eguberria', resumen: 'Pontifikatuaren lehen Urbi et Orbi mezua. Munduan zabalik dauden gatazka nagusien errepasoa (Ukraina, Gaza, Sudan, Myanmar, Haiti) eta bake desarmatuari deialdia. Aldez aurretiko bedeinkapen apostolikoa, indulgentzia osoa emanez, ixten du.', fragmento: 'Egun honetan Jainkoa ume egin den honetan, ahalguztidunak hauskortasuna hautatu duenean, Belengo aldera begiratzen dugu. Gaur egungo Belenei ere begiratzen diegu: Ukraina, Gaza, Sudan, Myanmar, Haiti, Kongo. Hondakin artean jaiotako haurrak. Errefuxiatuen kanpamentuetan erditzen ari diren amak. Haien guztien alde bake desarmatua eta desarmatzailea eskatzen dugu.' },
  { titulo: 'Bakearen 59. Mundu Egunerako mezua', lugar: 'Vatikano Hiria', ocasion: 'Maria Jainkoaren Amaren Solemnitatea', resumen: 'Pontifikatuaren Bakearen Mundu Egunerako lehen mezua. Izenburua: "Hitzak desarmatu, lurra desarmatu". Hizkuntza publikoari, desinformazioari, IA sortzaileari eta benetako gatazketako ondorioei buruzko hausnarketa.', fragmento: 'Bonbak baino lehen hitzak erortzen dira: gizatasuna kentzen dutenak, legitimitatea kentzen dutenak, indarkeria moralki prestatzen dutenak. Hitzak desarmatzea da lurra desarmatzeko lehen urratsa. Eta hori adimen artifizialak harrigarriko erraztasunez sortzen dituen hizkuntza sintetiko forma berrientzat ere balio du.' },
  { titulo: 'Erromatar Curiari urteko hitzaldia', lugar: 'Sala Clementina, Jauregi Apostolikoa', ocasion: 'Eguberriko zorionak Erromatar Curiari', resumen: 'Lehen urteko hitzaldia Curiari. Frantziskorekiko jarraitutasunean tonu erreformazalea markatzen du: sinpletasuna, deszentralizazioa eta zerbitzua. Hiru dikasterioren erreforma sartzen du eta lehen exhortazio apostolikoa, Dilexi Te, iragartzen du.', fragmento: 'Zerbitzatzen ez duen Curia batek ez du existitzeko arrazoirik. Ez gaitezen gortelariak izan, baizik eta Pedroren Ondorengoaren laguntzaileak eta Eliza partikularren zerbitzariak. Erreforma ez da bukatu: jarraituko du, ez aktibismoagatik, baizik eta Eliza beti dagoelako bihurtzearen bidean.' },
]

