// =============================================================================
// Getters
// =============================================================================

function getDiscursosDict(locale: Locale): DiscursoTranslation[] | null {
  switch (locale) {
    case 'en': return DISCURSOS_EN
    case 'it': return DISCURSOS_IT
    case 'fr': return DISCURSOS_FR
    case 'de': return DISCURSOS_DE
    case 'pt': return DISCURSOS_PT
    case 'ca': return DISCURSOS_CA
    case 'gl': return DISCURSOS_GL
    case 'eu': return DISCURSOS_EU
    default: return null
  }
}

export function getDiscursos(locale: Locale): Discurso[] {
  const dict = getDiscursosDict(locale)
  if (!dict) return discursos
  return discursos.map((d, i) => {
    const tr = dict[i]
    if (!tr) return d
    return { ...d, titulo: tr.titulo, lugar: tr.lugar, ocasion: tr.ocasion, resumen: tr.resumen, fragmento: tr.fragmento }
  })
}

export function getTiposDiscurso(locale: Locale): TipoDiscursoLabel[] {
  switch (locale) {
    case 'en': return TIPOS_DISCURSO_EN
    case 'it': return TIPOS_DISCURSO_IT
    case 'fr': return TIPOS_DISCURSO_FR
    case 'de': return TIPOS_DISCURSO_DE
    case 'pt': return TIPOS_DISCURSO_PT
    case 'ca': return TIPOS_DISCURSO_CA
    case 'gl': return TIPOS_DISCURSO_GL
    case 'eu': return TIPOS_DISCURSO_EU
    default: return tiposDiscurso
  }
}

export { discursos, tiposDiscurso }
export type { Discurso, TipoDiscursoLabel }
